extern "C" {
// ============================================================================
// [EN] Exported libyuv Functions (Matching AArch64 Opcodes @ 0xce8c..0xdc04)
// [VN] Các hàm xuất khẩu của libyuv (Khớp mã máy AArch64 @ 0xce8c..0xdc04)
// ============================================================================
std::uint32_t HashDjb2_C(const std::uint8_t* src, std::uint64_t count, std::uint32_t seed) noexcept {
    std::uint32_t hash = seed;
    if (src == nullptr) return hash;
    for (std::uint64_t i = 0; i < count; ++i) {
        hash = hash * 33U + static_cast<std::uint32_t>(src[i]);
    }
    return hash;
}

std::uint32_t HashDjb2(const std::uint8_t* src, std::uint64_t count, std::uint32_t seed) noexcept {
    return HashDjb2_C(src, count, seed); // 0x00ce8c
}

std::uint32_t SumSquareError_C(const std::uint8_t* src_a, const std::uint8_t* src_b, int count) noexcept {
    if (src_a == nullptr || src_b == nullptr || count <= 0) return 0U;
    std::uint32_t sse = 0U;
    for (int i = 0; i < count; ++i) {
        int diff = static_cast<int>(src_a[i]) - static_cast<int>(src_b[i]);
        sse += static_cast<std::uint32_t>(diff * diff);
    }
    return sse;
}

double SumSquareErrorToPsnr(std::uint64_t sse, std::uint64_t count) noexcept {
    constexpr double kMaxPsnr = 128.0;
    if (sse == 0ULL || count == 0ULL) return kMaxPsnr; // 0x00d168: cbz x0
    double mse = static_cast<double>(count) / static_cast<double>(sse);
    double psnr = 10.0 * std::log10(255.0 * 255.0 * mse);
    return (psnr > kMaxPsnr) ? kMaxPsnr : psnr;
}

int I420Copy(const std::uint8_t* src_y, int src_stride_y,
             const std::uint8_t* src_u, int src_stride_u,
             const std::uint8_t* src_v, int src_stride_v,
             std::uint8_t* dst_y, int dst_stride_y,
             std::uint8_t* dst_u, int dst_stride_u,
             std::uint8_t* dst_v, int dst_stride_v,
             int width, int height) noexcept {
    if (!src_y || !src_u || !src_v || !dst_y || !dst_u || !dst_v || width <= 0 || height == 0) {
        return -1;
    }
    int abs_h = (height < 0) ? -height : height;
    int half_w = (width + 1) >> 1;
    int half_h = (abs_h + 1) >> 1;
    for (int y = 0; y < abs_h; ++y) {
        std::memcpy(dst_y + y * dst_stride_y, src_y + y * src_stride_y, static_cast<std::size_t>(width));
    }
    for (int y = 0; y < half_h; ++y) {
        std::memcpy(dst_u + y * dst_stride_u, src_u + y * src_stride_u, static_cast<std::size_t>(half_w));
        std::memcpy(dst_v + y * dst_stride_v, src_v + y * src_stride_v, static_cast<std::size_t>(half_w));
    }
    return 0;
}

int NV12ToI420(const std::uint8_t* src_y, int src_stride_y,
               const std::uint8_t* src_uv, int src_stride_uv,
               std::uint8_t* dst_y, int dst_stride_y,
               std::uint8_t* dst_u, int dst_stride_u,
               std::uint8_t* dst_v, int dst_stride_v,
               int width, int height) noexcept {
    if (!src_y || !src_uv || !dst_y || !dst_u || !dst_v || width <= 0 || height == 0) return -1;
    int abs_h = (height < 0) ? -height : height;
    int half_w = (width + 1) >> 1;
    int half_h = (abs_h + 1) >> 1;
    for (int y = 0; y < abs_h; ++y) {
        std::memcpy(dst_y + y * dst_stride_y, src_y + y * src_stride_y, static_cast<std::size_t>(width));
    }
    for (int y = 0; y < half_h; ++y) {
        const std::uint8_t* row_uv = src_uv + y * src_stride_uv;
        std::uint8_t* row_u = dst_u + y * dst_stride_u;
        std::uint8_t* row_v = dst_v + y * dst_stride_v;
        for (int x = 0; x < half_w; ++x) {
            row_u[x] = row_uv[2 * x + 0];
            row_v[x] = row_uv[2 * x + 1];
        }
    }
    return 0;
}

int NV21ToI420(const std::uint8_t* src_y, int src_stride_y,
               const std::uint8_t* src_vu, int src_stride_vu,
               std::uint8_t* dst_y, int dst_stride_y,
               std::uint8_t* dst_u, int dst_stride_u,
               std::uint8_t* dst_v, int dst_stride_v,
               int width, int height) noexcept {
    return NV12ToI420(src_y, src_stride_y, src_vu, src_stride_vu,
                      dst_y, dst_stride_y, dst_v, dst_stride_v, dst_u, dst_stride_u, width, height);
}
} // extern "C"
